using System;
using System.IO;
using System.Linq;
using BuyBidBlow.Systems.Match;
using BuyBidBlow.Systems.Types;
using BuyBidBlow.Systems.Auction;
using BuyBidBlow.Props;
using BuyBidBlow.UI.Auction;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
namespace BuyBidBlow.PlayerUISandbox.Editor {
[InitializeOnLoad] public static class MatchIntegrationBuilder {
static MatchIntegrationBuilder(){EditorApplication.update+=()=>{if(!File.Exists("Library/MatchIntegration.request")||EditorApplication.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating)return;File.Delete("Library/MatchIntegration.request");try{Build();File.WriteAllText("Library/MatchIntegration.result","PASS");}catch(Exception e){File.WriteAllText("Library/MatchIntegration.result",e.ToString());Debug.LogException(e);}};}
const string Root="Assets/Project/Dev/Sandbox/Interface/PlayerUI";
static Text Label(Transform parent,string name,Vector2 pos,Vector2 size,string value){var g=new GameObject(name,typeof(RectTransform),typeof(Image));g.transform.SetParent(parent,false);var r=(RectTransform)g.transform;r.anchorMin=r.anchorMax=r.pivot=new Vector2(.5f,1);r.anchoredPosition=pos;r.sizeDelta=size;g.GetComponent<Image>().color=new Color(.015f,.04f,.035f,.94f);var child=new GameObject("Text",typeof(RectTransform),typeof(Text));child.transform.SetParent(g.transform,false);var cr=(RectTransform)child.transform;cr.anchorMin=Vector2.zero;cr.anchorMax=Vector2.one;cr.offsetMin=new Vector2(12,8);cr.offsetMax=new Vector2(-12,-8);var t=child.GetComponent<Text>();t.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Font/public/static/alternative/Pretendard-Regular.ttf");t.fontSize=22;t.alignment=TextAnchor.MiddleCenter;t.color=new Color(1,.93f,.74f);t.text=value;return t;}
public static void Build(){TradingRestore.Apply();var scene=EditorSceneManager.OpenScene(Root+"/SC_PlayerUI.unity",OpenSceneMode.Single);var all=scene.GetRootGameObjects();var c=all.SelectMany(g=>g.GetComponentsInChildren<PlayerUIController>(true)).Single();var old=c.GetComponentInChildren<MatchUIBridge>(true);if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var oldRoot=all.FirstOrDefault(g=>g.name=="Local Match Runtime");if(oldRoot)UnityEngine.Object.DestroyImmediate(oldRoot);var go=new GameObject("Local Match Runtime");go.transform.SetParent(c.transform,false);var b=go.AddComponent<MatchUIBridge>();b.settingsFile=AssetDatabase.LoadAssetAtPath<TextAsset>("Assets/Project/Content/Match/MatchSettings.json");b.controller=c;c.bridge=b;var cameraDataType=Type.GetType("UnityEngine.Rendering.Universal.UniversalAdditionalCameraData, Unity.RenderPipelines.Universal.Runtime");if(cameraDataType!=null&&!c.view.GetComponent(cameraDataType))c.view.gameObject.AddComponent(cameraDataType);var displays=all.SelectMany(g=>g.GetComponentsInChildren<AuctionEnvelopeDisplay>(true)).ToArray();b.envelope=displays.FirstOrDefault(d=>d.gameObject.name=="Auction Envelope Display")??displays.FirstOrDefault();foreach(var duplicate in displays)if(duplicate!=b.envelope)UnityEngine.Object.DestroyImmediate(duplicate.gameObject);b.exchangeBoard=all.SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).FirstOrDefault(t=>t.name=="Exchange Prices - World Space Editable");
foreach(var t in c.hud.GetComponentsInChildren<Transform>(true).Where(t=>new[]{"Live Lot Details","Private Information","Active Bet","Local Session Note"}.Contains(t.name)).ToArray())if(t)UnityEngine.Object.DestroyImmediate(t.gameObject);
var lot=Label(c.hud.transform,"Live Lot Details",new Vector2(0,-185),new Vector2(420,155),"경매 상품");lot.transform.parent.gameObject.SetActive(false);
var panel=c.hud.GetComponent<AuctionPanelView>();if(!panel)panel=c.hud.AddComponent<AuctionPanelView>();var so=new SerializedObject(panel);so.FindProperty("header").objectReferenceValue=c.auctionHeader;so.FindProperty("controls").objectReferenceValue=c.auctionControls;so.FindProperty("lotDetails").objectReferenceValue=lot;so.ApplyModifiedPropertiesWithoutUndo();b.auctionPanel=panel;
b.privateInfo=Label(c.hud.transform,"Private Information",new Vector2(0,-350),new Vector2(680,310),"내 정보");b.privateInfo.transform.parent.gameObject.SetActive(false);
b.betStatus=Label(c.hud.transform,"Active Bet",new Vector2(-698,-255),new Vector2(460,44),"");b.betStatus.transform.parent.gameObject.SetActive(false);
var note=Label(c.hud.transform,"Local Session Note",new Vector2(0,-3),new Vector2(680,40),"로컬 테스트 · 기본 3인 등록 / 나머지 대기 · I 내 정보");note.fontSize=15;
foreach(var station in UnityEngine.Object.FindObjectsByType<UIInteractionTarget>(FindObjectsSortMode.None)){if(station.kind!=UIInteractionTarget.Kind.AuctionSeat){var pos=station.transform.position;pos.y=.9f;pos.z=-3.3f;station.transform.position=pos;station.transform.localScale=new Vector3(1.9f,1.8f,.15f);var renderer=station.GetComponent<Renderer>();if(renderer)renderer.enabled=false;var label=station.transform.Find("Station Label");if(label)label.gameObject.SetActive(false);}}
PrefabUtility.SaveAsPrefabAsset(c.hud,Root+"/Prefabs/PF_PlayerHUD.prefab");PrefabUtility.SaveAsPrefabAsset(c.gameObject,Root+"/Prefabs/PF_PlayerUIRig.prefab");EditorUtility.SetDirty(c);EditorUtility.SetDirty(b);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Check();}
static void Ensure(bool condition,string message){if(!condition)throw new Exception(message);}
public static void Check(){var settings=JsonUtility.FromJson<MatchSettings>(File.ReadAllText("Assets/Project/Content/Match/MatchSettings.json"));var p=new PlayerId("P1");var p2=new PlayerId("P2");var p3=new PlayerId("P3");var players=new[]{p,p2,p3};var g=new MatchEngine(settings,12345,players,0);int price=g.Price(Company.Straw);g.Trade(p,Company.Straw,1,true,0);Ensure(g.Snapshot(p).Cash==200-price&&g.Stock(Company.Straw)==11,"Buy/inventory");g.Trade(p,Company.Straw,1,false,0);Ensure(g.Snapshot(p).Cash==200&&g.Stock(Company.Straw)==12,"Sell return");g.Trade(p,Company.Straw,13,true,0);Ensure(g.Snapshot(p).Cash==200&&g.Stock(Company.Straw)==12,"Reject whole request");g.ToggleBet(p,Company.Straw,0);Ensure(g.HasBet(p)&&g.Snapshot(p).Cash==200-price,"Bet spend");g.ToggleBet(p,Company.Straw,0);Ensure(!g.HasBet(p)&&g.Snapshot(p).Cash==200,"Bet refund");g.ToggleBet(p,Company.Straw,0);Ensure(g.HasBet(p),"Bet reentry");g.ToggleBet(p,Company.Straw,0);
var before=g.Snapshot(p);g.Trade(p,Company.Straw,1,true,60);Ensure(g.Snapshot(p).Cash==before.Cash,"Deadline equality");g.Tick(60);Ensure(g.Round==2&&g.Auction.Open!=null,"Round/auction start");g.Bid(p,30,false,60);Ensure(g.Snapshot(p).Reserved==30,"Bid reserve");g.Trade(p,Company.Brick,100,true,61);Ensure(g.Snapshot(p).Reserved==30,"Reserve protected");g.Bid(p2,31,false,61);Ensure(g.Snapshot(p).Reserved==0,"Outbid release");int awards=0;g.InformationAwarded+=r=>{awards++;};g.Bid(p,100,false,120);Ensure(g.Snapshot(p).Reserved==0,"Open deadline equality");g.Tick(120);Ensure(awards==1&&g.Auction.Secret!=null&&g.Snapshot(p2).Cash==169,"Public settlement and secret start");g.Bid(p,40,false,120);g.Bid(p2,40,false,121);g.Bid(p,41,false,122);g.Bid(p,40,false,123);g.Tick(180);Ensure(g.Snapshot(p2).Cash==129&&g.Snapshot(p).Reserved==0,"Secret revised tie order");g.Tick(10000);Ensure(g.Complete&&g.Round==17,"All rounds complete");Ensure(g.Standings().Contains("위"),"Ranking");
var betGame=new MatchEngine(settings,12345,players,0);int old=betGame.Price(Company.Straw);betGame.ToggleBet(p,Company.Straw,0);betGame.Tick(60);Ensure(betGame.Snapshot(p).Cash==200-old+(betGame.Price(Company.Straw)<old?old*2:0),"Bet actual close settlement");File.WriteAllText(Root+"/MatchIntegrationVerification.txt","PASS: buy/sell finite supply, whole rejection, bet refund/re-entry/settlement, deadline equality, public reserve/release/settlement, secret modification tie order, all 17 closes and standings. Local authority; no networking or AI.");Debug.Log("MATCH INTEGRATION CHECKS PASS");}
}
}